import os

from datadog import initialize, api


def configure_client(api_key, app_key):
    options = {
        'api_key': api_key,
        'app_key': app_key
    }
    initialize(**options)


def query_logs(query, start, end):
    response = api.Log.search(
        query=query,
        start=start,
        end=end
    )
    return response


def ingest_log(message, source='python', service='example-service'):
    api.Log.send(
        message=message,
        source=source,
        service=service
    )

import boto3

def write_correlated_logs(log_group_name, log_stream_name, correlation_id, log_event):
    client = boto3.client('logs')
    client.put_log_events(
        logGroupName=log_group_name,
        logStreamName=log_stream_name,
        logEvents=[{
            'timestamp': int(round(time.time() * 1000)),
            'message': f"{correlation_id}: {log_event}"
        }]
